        v6 = M8(v3 + 25) & 0x3F;
        M8(v3 + 26) &= 0xFu;
        M8(v3 + 25) = v6 >> 1;
        v7 = M8(v3 + 26);
        M8(v3 + 27) = 0;
        if ( !M8(v7 + v3 + 1) )
          M8(v3 + 26) = 0;
