#define V4_ARENA 0x04000000UL

typedef struct dec4v_ctx {
    unsigned char *mem;
    unsigned long hi;
    Uha4ReadCb rcb;
    void *rctx;
    Uha4WriteCb wcb;
    void *wctx;
    unsigned in_pos;
    unsigned in_avail;
    unsigned out_fill;
    unsigned long out_tot;
    unsigned long out_len;
    int err;
    /* arena offsets of the 64KB stream buffers (dword_436ED0/436ED4) */
    unsigned long in_buf;
    unsigned long out_buf;
} dec4v_ctx;

static unsigned int d4v_o(unsigned int o)
{
    if (o > (unsigned)(V4_ARENA - 8)) o = (unsigned)(V4_ARENA - 8);
    return o;
}
#define V4O(o)  d4v_o((unsigned)(o))
#define Q4G8(a)   (*(unsigned char  *)(void *)(c->mem + V4O(a)))
#define Q4G16(a)  (*(unsigned short *)(void *)(c->mem + V4O(a)))
#define Q4G32(a)  (*(unsigned int   *)(void *)(c->mem + V4O(a)))
#define Q4M8(o)   (*(unsigned char  *)(void *)(c->mem + V4O(o)))
#define Q4M16(o)  (*(unsigned short *)(void *)(c->mem + V4O(o)))
#define Q4M32(o)  (*(unsigned int   *)(void *)(c->mem + V4O(o)))

/* sub_40D070: bump allocator over the arena (the original manages a real
 * heap with freelists; sizes/aligns below mirror the init sequence). */
unsigned long d4v_alloc(dec4v_ctx *c, unsigned long size)
{
    unsigned long p;
    if (size == 0 || size >= (unsigned long)(V4_ARENA - 16)) return 0;
    p = (c->hi + 15UL) & ~15UL;
    if (p + size > (unsigned long)V4_ARENA) return 0;
    c->hi = p + size;
    return p;
}

/* sub_425810(ebx=count, edx=dst, eax=val): fill count u16 with val. */
void d4v_fill16(dec4v_ctx *c, unsigned int count, unsigned int dst,
                       unsigned int val)
{
    unsigned int i;
    for (i = 0; i < count; i++)
        Q4M16(dst + 2 * i) = (unsigned short)val;
}

/* sub_426EE0: one-time prefix sums word_437968 += word_437966. Both tables
 * are BSS-zero in the original (437966 has no writers) so this only clears
 * byte_43F968; kept as the loop for fidelity. */
void d4v_prices(dec4v_ctx *c)
{
    if (Q4M8(D4V_PRICE_DONE)) {
        unsigned int a;
        for (a = 1; a < 0x4000; a++)
            Q4M16(D4V_TBL_PRICE_SUM + 2 * a) += Q4M16(D4V_TBL_PRICE_SRC + 2 * a);
        Q4M8(D4V_PRICE_DONE) = 0;
    }
}

int d4v_init_file(dec4v_ctx *c, int method, unsigned int al_in);

/* Header +9 bit6 selects the kennedy.xls PPM special case.
 * Set by the container before a 0.4 PPM decode. */
static unsigned char g_dec4v_flags2;

void UhaDec4_04SetFlags2(unsigned char flags2)
{
    g_dec4v_flags2 = flags2;
}

int UhaDec4_04Init(void **pctx, int method)
{
    dec4v_ctx *c;
    int rc;
    c = (dec4v_ctx *)calloc(1, sizeof(*c));
    if (!c) return 2;
    c->mem = (unsigned char *)calloc(1, (size_t)V4_ARENA);
    if (!c->mem) { free(c); return 2; }
    c->hi = 0x1000;
    c->in_buf = d4v_alloc(c, 65536UL);
    c->out_buf = d4v_alloc(c, 65536UL);
    if (!c->in_buf || !c->out_buf) { free(c->mem); free(c); return 2; }
    /* Model blocks must live ABOVE the fixed globals window (DGROUP image
     * 0x42E000-0x440000, .bss 0x440000-0x45DA00); bumping from 0x21000
     * would pave over it. 0x600000 + ~53MB footprint < 64MB arena. */
    c->hi = 0x600000UL;
    /* DGROUP static image (config bytes, pointer tables, price seeds):
     * 1:1 copy so absolute-address reads match the original. */
    {
        /* d4v_dgroup defined above (was extern uha04_dec4_dg.c) */
        memcpy(c->mem + D4V_DGROUP_BASE, d4v_dgroup, 73728);
    }
    rc = d4v_init_file(c, method, 0);
    if (rc) { free(c->mem); free(c); return rc; }
    *pctx = c;
    return 0;
}

void UhaDec4_04Free(void *ctx)
{
    dec4v_ctx *c = (dec4v_ctx *)ctx;
    if (!c) return;
    free(c->mem);
    free(c);
}

/* ---- byte pump (sub_4220B0 / sub_4221F0 / sub_422110 / sub_421F50) ---- */

/* sub_4285A0: memmove used by the 421FA0 compact path
 * (dst=eax, src=edx, n=ebx; arena offsets). */
static void d4v_memmove(dec4v_ctx *c, unsigned int dst, unsigned int src,
                        unsigned int n)
{
    memmove(c->mem + V4O(dst), c->mem + V4O(src), (size_t)n);
}

/* indirect stream reader ([4370D8]): read up to n bytes to dst, return
 * bytes read (0 at EOF). 45CD24 is NOT bumped here: consumption is
 * counted per byte by sub_4220B0. */
static unsigned int d4v_read_stream(dec4v_ctx *c, unsigned int dst,
                               unsigned int n, unsigned int aux)
{
    int r;
    (void)aux;
    if (c->err) return 0;
    if (n > 65536U) n = 65536U;
    if (n == 0) return 0;
    r = c->rcb(c->rctx, c->mem + V4O(dst), n);
    if (r <= 0) return 0;
    return (unsigned int)r;
}

/* sub_421F50: refill input buffer through the [4370D8] reader. */
static void d4v_refill(dec4v_ctx *c)
{
    unsigned int got;
    if (c->err) { Q4G32(D4V_IO_IN_VALID) = 0; Q4G32(D4V_IO_IN_POS) = 0; return; }
    Q4G32(D4V_IO_SNAP_IN) = Q4G32(D4V_IO_IN_TOTAL);
    Q4G32(D4V_IO_IN_POS) = 0;
    Q4G32(D4V_IO_SNAP_OUT) = Q4G32(D4V_IO_OUT_TOTAL);
    got = d4v_read_stream(c, Q4G32(D4V_IO_IN_PTR), Q4G32(D4V_IO_IN_CAP), 0);
    Q4G32(D4V_IO_IN_VALID) = got;
    if (!got) {
        Q4G32(D4V_IO_ERR) = 3;
        c->err = 3;
    }
}

/* sub_4220B0: input byte. Increments 45CD24. */
static unsigned int d4v_get_byte(dec4v_ctx *c)
{
    unsigned int pos;
    if (Q4G32(D4V_IO_IN_POS) >= Q4G32(D4V_IO_IN_VALID))
        d4v_refill(c);
    if (c->err) return 0;
    pos = Q4G32(D4V_IO_IN_POS);
    Q4G32(D4V_IO_IN_TOTAL) = Q4G32(D4V_IO_IN_TOTAL) + 1;
    Q4G32(D4V_IO_IN_POS) = pos + 1;
    return (unsigned int)Q4M8(Q4G32(D4V_IO_IN_PTR) + pos);
}

/* forward flush used by put */
static void d4v_flush_out(dec4v_ctx *c);

/* sub_4221F0: output byte (al). Appends at 436ED4+45CD1C, bumps 45CD1C
 * and 45CD28, flushes via 422110 when 45CD1C reaches 45CD10. */
static void d4v_put_byte(dec4v_ctx *c, unsigned int b)
{
    unsigned int at;
    if (c->err) return;
    at = Q4G32(D4V_IO_OUT_POS);
    Q4M8(Q4G32(D4V_IO_OUT_PTR) + at) = (unsigned char)b;
    Q4G32(D4V_IO_OUT_POS) = at + 1;
    Q4G32(D4V_IO_OUT_TOTAL) = Q4G32(D4V_IO_OUT_TOTAL) + 1;
    if (at + 1 >= Q4G32(D4V_IO_OUT_CAP))
        d4v_flush_out(c);
}

/* sub_422110: flush output buffer through the write callback. */
static void d4v_flush_out(dec4v_ctx *c)
{
    unsigned int n = Q4G32(D4V_IO_OUT_POS);
    if (c->err) return;
    if (n) {
        if (c->wcb(c->wctx, c->mem + Q4G32(D4V_IO_OUT_PTR), n) != 0)
            c->err = 4;
        Q4G32(D4V_IO_OUT_POS) = 0;
    }
}

/* ---- range coder reset (sub_426F70) ----
 * NOTE: the 417DA0 decode driver calls sub_426F30, not this; 426F70
 * belongs to the 41CE30 block-driver path. Kept for reference. */
static void d4v_rc_reset(dec4v_ctx *c) /* range reset (orig d4v_426f70) */
{
    Q4G32(D4V_RC_CODE_LO) = 0;
    Q4G32(D4V_RC_CODE_HI) = 0;
    Q4G32(D4V_RC_CARRY_CNT) = 0;
    Q4G32(D4V_RC_PENDING_B) = 0;
    Q4G32(D4V_RC_RANGE) = 0xFFFFFFFFUL;
}

/* ---- range prime (sub_426F30): 45D0B8 = 0, 45D0BC = 0xFFFFFFFF, then
 * fold 5 input bytes big-endian into 45D0B8 (the decode code register).
 * Entry regs: none. */
static void d4v_rc_init(dec4v_ctx *c) /* range prime: 5 bytes BE (orig d4v_426f30) */
{
    unsigned int edx;
    unsigned int ecx;
    unsigned int eax;
    Q4G32(D4V_RC_CODE) = 0; /* 0x426F39 */
    Q4G32(D4V_RC_RANGE) = 0xFFFFFFFFUL; /* 0x426F3F */
    eax = 0;
    for (edx = 0; edx < 5; edx++) { /* 0x426F45 loc_426F45 */
        ecx = 0; /* 0x426F45 xor ecx,ecx */
        ecx = d4v_get_byte(c) & 0xFFU; /* 0x426F47 call 4220B0; 0x426F4C mov cl,al */
        eax = Q4G32(D4V_RC_CODE); /* 0x426F4E */
        eax = ((eax << 8) | ecx) & 0xFFFFFFFFUL; /* 0x426F53 shl; 0x426F56 or */
        Q4G32(D4V_RC_CODE) = eax; /* 0x426F59 */
    } /* 0x426F5E cmp edx,5; 0x426F61 jb */
}


/* Range renormalize: while *prange < 0x1000000, shift in one byte.
 * Callers keep code/range in locals and store back to
 * D4V_RC_CODE/D4V_RC_RANGE after. (3 sites in d4v_rc_primer.) */
static void d4v_rcrenorm(dec4v_ctx *c, unsigned int *pcode, unsigned int *prange)
{
    while (*prange < 0x1000000UL) {
        unsigned int b = d4v_get_byte(c);
        *pcode = ((*pcode << 8) | (b & 0xFFU)) & 0xFFFFFFFFUL;
        *prange = (*prange << 8) & 0xFFFFFFFFUL;
    }
}

/* Range renormalize preserving caller byte register (goto-style sites).
 * *pcode/*prange are locals (e_ecx/e_edx or ecx/edx); *pbyte is the
 * caller register (e_eax/eax) clobbered with the last byte read. */
static void d4v_rcrenorm_reg(dec4v_ctx *c, unsigned int *pcode, unsigned int *prange, unsigned int *pbyte)
{
    while (*prange < 0x1000000UL) {
        *pbyte = d4v_get_byte(c) & 0xFFU;
        *pcode = ((*pcode << 8) | *pbyte) & 0xFFFFFFFFUL;
        *prange = (*prange << 8) & 0xFFFFFFFFUL;
    }
}


/* ---- range reader init (sub_41F2A0) ----
 * Entry esi = 0x45AF68 area base (constant; the second half sets it
 * explicitly and the first half uses the same [eax+4]/[eax+8] shape). */
static void d4v_rc_primer(dec4v_ctx *c) /* range reader init + primer (orig d4v_41f2a0) */
{
    unsigned int edx;
    unsigned int ecx;
    unsigned int eax;
    unsigned int ebx;
    unsigned int edi;
    unsigned int esi = D4V_RSLOT_LO;
    unsigned int ebp;
    unsigned int var_1c;
    edx = 2; ecx = 2;
    Q4G32(D4V_RSLOT_LO) = edx;
    eax = Q4G32(D4V_RC_RANGE);
    edx = 0;
    /* div ecx(2) */
    ebx = eax; eax = ebx / ecx;
    edx = 0;
    Q4G32(D4V_RC_RANGE) = eax;
    ecx = eax;
    eax = Q4G32(D4V_RC_CODE);
    /* div ecx */
    ebx = eax; eax = ecx ? ebx / ecx : 0; edx = ecx ? ebx % ecx : 0;
    ebx = eax;
    Q4G8(D4V_CTX_B_45C67F) = (unsigned char)ebx;
    eax = ebx;
    Q4G32(D4V_RSLOT_MID) = eax;
    eax = ebx + 1;
    Q4G32(D4V_RSLOT_HI) = eax;
    eax = esi;
    edx = Q4M32(eax + 8);
    eax = Q4M32(eax + 4);
    ecx = Q4G32(D4V_RC_RANGE);
    edx = edx - eax;
    eax = eax * ecx;
    edx = edx * ecx;
    ecx = Q4G32(D4V_RC_CODE);
    ecx = ecx - eax;
    d4v_rcrenorm(c, &ecx, &edx);
    Q4G32(D4V_RC_CODE) = ecx;
    Q4G32(D4V_RC_RANGE) = edx;
    if (Q4G8(D4V_CTX_B_45C67F))
        return;
    ecx = 0;
    var_1c = 0;
    esi = D4V_RSLOT_LO;
    ebp = 2;
    for (;;) {
        ebx = 0x800;
        Q4G32(D4V_RSLOT_LO) = ebx;
        ecx = ebx;
        ebx = 0;
        eax = Q4G32(D4V_RC_RANGE);
        edx = 0;
        ebx = eax; eax = ebx / ecx;
        Q4G32(D4V_RC_RANGE) = eax;
        ecx = eax;
        eax = Q4G32(D4V_RC_CODE);
        ebx = eax; eax = ecx ? ebx / ecx : 0;
        ebx = eax & 0xFFFFU;
        Q4G32(D4V_RSLOT_MID) = ebx;
        eax = ebx + 1;
        Q4G32(D4V_RSLOT_HI) = eax;
        eax = esi;
        edx = Q4M32(eax + 8);
        eax = Q4M32(eax + 4);
        ecx = Q4G32(D4V_RC_RANGE);
        edx = edx - eax;
        eax = eax * ecx;
        edx = edx * ecx;
        ecx = Q4G32(D4V_RC_CODE);
        ecx = ecx - eax;
        d4v_rcrenorm(c, &ecx, &edx);
        Q4G32(D4V_RC_CODE) = ecx;
        Q4G32(D4V_RC_RANGE) = edx;
        {
            unsigned int cl = var_1c & 0xFFU;
            eax = var_1c;
            edi = Q4G32(D4V_PREFIX_SUM_TMP);
            Q4G32(D4V_RSLOT_LO) = ebp;
            eax = eax + 0x0BU;
            ebx = (ebx << cl) & 0xFFFFFFFFUL;
            var_1c = eax;
            edi = edi + ebx;
            ecx = ebp;
            Q4G32(D4V_PREFIX_SUM_TMP) = edi;
        }
        ebx = 0;
        eax = Q4G32(D4V_RC_RANGE);
        edx = 0;
        ebx = eax; eax = ecx ? ebx / ecx : 0;
        Q4G32(D4V_RC_RANGE) = eax;
        ecx = eax;
        eax = Q4G32(D4V_RC_CODE);
        ebx = eax; eax = ecx ? ebx / ecx : 0;
        ebx = eax & 0xFFFFU;
        Q4G32(D4V_RSLOT_MID) = ebx;
        eax = ebx + 1;
        Q4G32(D4V_RSLOT_HI) = eax;
        eax = esi;
        edx = Q4M32(eax + 8);
        eax = Q4M32(eax + 4);
        ecx = Q4G32(D4V_RC_RANGE);
        edx = edx - eax;
        eax = eax * ecx;
        edx = edx * ecx;
        ecx = Q4G32(D4V_RC_CODE);
        ecx = ecx - eax;
        d4v_rcrenorm(c, &ecx, &edx);
        Q4G32(D4V_RC_CODE) = ecx;
        Q4G32(D4V_RC_RANGE) = edx;
        if (!ebx) break;
    }
    Q4G32(D4V_LZP_TRIGGER) = Q4G32(D4V_PREFIX_SUM_TMP);
}

/* ---- shared worker helpers (single copy; draft-local copies
 * of these macros/helpers were stripped at integration) ---- */
#define U32MASK 0xFFFFFFFFUL
#define ADD8_LO(r,v) ((r) = ((r) & 0xFFFFFF00UL) | (((r) + (v)) & 0xFFUL))
#define SUB8_LO(r,v) ((r) = ((r) & 0xFFFFFF00UL) | (((r) - (v)) & 0xFFUL))
#define DECB_LO(r) ((r) = ((r) & 0xFFFFFF00UL) | (((r) - 1) & 0xFFUL))
#define ADD8_HI(r,v) ((r) = ((r) & 0xFFFF00FFUL) | ((((((r) >> 8) & 0xFFUL) + (v)) & 0xFFUL) << 8))
#define D4V_SP 0x0F000000u /* stand-in stack base for lea modeling (418830);
 * values derived from it are only incremented/compared, never dereferenced */

/* Exact 32-bit arithmetic shift right (x86 SAR semantics, count masked). */
static unsigned long d4v_sar(unsigned long v, unsigned int n)
{
    unsigned long s;
    n &= 31u;
    if (n == 0)
        return v & U32MASK;
    if (v & 0x80000000UL) {
        s = (0xFFFFFFFFUL << (32u - n)) & U32MASK;
        return (s | (v >> n)) & U32MASK;
    }
    return (v >> n) & U32MASK;
}

/* sub_40D570-style byte fill (ebx=len, edx=val, eax=dst in the original). */
static void d4v_fill(dec4v_ctx *c, unsigned int len, unsigned int dst,
                     unsigned int val)
{
    memset(c->mem + V4O(dst), (int)(val & 0xFFU), (size_t)len);
}

