static const unsigned long d3u_dgroup_base = 0x00428000UL;
static const unsigned long d3u_dgroup_len = 54476UL;


#define V3_ARENA 0x04000000UL


typedef struct dec3w_ctx {
    unsigned char *mem;
    unsigned long hi;
    Uha4ReadCb rcb;
    void *rctx;
    Uha4WriteCb wcb;
    void *wctx;
    int err;
    int method;
    unsigned long in_buf;
    unsigned long out_buf;
} dec3w_ctx;

static unsigned int d3w_o(unsigned int o)
{
    if (o > (unsigned)(V3_ARENA - 8)) o = (unsigned)(V3_ARENA - 8);
    return o;
}
#define V3O(o)  d3w_o((unsigned)(o))
#define Q3G8(a)   (*(unsigned char  *)(void *)(c->mem + V3O(a)))
#define Q3G16(a)  (*(unsigned short *)(void *)(c->mem + V3O(a)))
#define Q3G32(a)  (*(unsigned int   *)(void *)(c->mem + V3O(a)))
#define Q3M8(o)   (*(unsigned char  *)(void *)(c->mem + V3O(o)))
#define Q3M16(o)  (*(unsigned short *)(void *)(c->mem + V3O(o)))
#define Q3M32(o)  (*(unsigned int   *)(void *)(c->mem + V3O(o)))
#define Q3MASK 0xFFFFFFFFUL

/* sub_40C9C0-style byte fill (ebx=len, eax=dst, edx=val). */
void d3u_fill(dec3w_ctx *c, unsigned int len, unsigned int dst,
              unsigned int val)
{
    memset(c->mem + V3O(dst), (int)(val & 0xFFU), (size_t)len);
}

